            } else if (event.key === 'End') {
              event.preventDefault();
              for (let index = matches.length - 1; index >= 0; index -= 1) {
                if (!selected.has(matches[index].id)) {
                  setActive(index);
                  break;
                }
              }
            }
          }}
        />
