              setQuery('');
              inputRef.current?.focus();
            }}
          >
            <IconClose />
          </button>
        ) : null}
      </div>
      {open ? (
        <div className="results" role="listbox" id={listId} aria-label="Cities">
          {matches.length === 0 ? (
            <p className="results-empty">No cities match “{query.trim()}”.</p>
          ) : (
