import { describe, expect, it } from 'vitest';
import { parseState } from './storage';

describe('parseState', () => {
  it('returns defaults for an empty browser', () => {
    expect(parseState(null)).toMatchObject({
      cityIds: ['san-francisco', 'denpasar', 'geneva'],
      mode: 'meeting',
      wake: 7,
      sleep: 23,
      format: '12',
