.field { display: flex; flex-direction: column; gap: 6px; color: var(--muted); font-size: 12px; font-weight: 600; }
.field select {
  height: 38px;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: var(--bg);
  color: var(--text);
  padding: 0 10px;
  font-weight: 650;
}
.popover .segment { width: 100%; }
.popover .segment button { flex: 1; }

.stack { display: flex; flex-direction: column; gap: 14px; margin-top: 22px; }

.summary {
  padding: 14px 16px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(62, 224, 122, 0.1), rgba(62, 224, 122, 0.03));
  border: 1px solid rgba(62, 224, 122, 0.24);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.summary.is-empty {
  background: rgba(255, 193, 77, 0.07);
  border-color: rgba(255, 193, 77, 0.28);
}
.summary-kicker { color: var(--muted); font-size: 12px; font-weight: 650; letter-spacing: 0.04em; text-transform: uppercase; }
.summary-main, .badges, .base-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.summary-count { font-size: 1.35rem; letter-spacing: -0.04em; font-weight: 700; }
.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(62, 224, 122, 0.16);
  color: #d8ffe8;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 550;
}
.base-list { display: flex; flex-direction: column; }
.base-line { padding: 8px 0; border-top: 1px solid var(--line); }
.base-line:first-child { border-top: 0; padding-top: 2px; }
.who { min-width: 148px; font-weight: 700; }
.base-count { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 68px; }
.warning { color: var(--amber); font-weight: 700; }
.need-more { color: var(--muted); font-size: 14px; }

.search { position: relative; z-index: 30; max-width: 460px; }
.search-field {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  padding: 0 12px;
  border-radius: 12px;
  border: 1px solid var(--line-strong);
  background: var(--panel);
}
.search-field:focus-within {
  border-color: rgba(62, 224, 122, 0.75);
  box-shadow: 0 0 0 3px rgba(62, 224, 122, 0.16);
}
.search-icon { color: var(--faint); display: grid; }
.search-field input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: none;
  background: transparent;
  font-size: 14px;
}
.search-field input::placeholder { color: var(--faint); }
.clear {
  display: grid;
  place-items: center;
  width: 28px;
