:root {
  --bg: #090b0a;
  --panel: #141916;
  --panel-2: #1c2420;
  --line: rgba(232, 240, 230, 0.08);
  --line-strong: rgba(232, 240, 230, 0.16);
  --text: #f4f7f2;
  --muted: #a7b4a8;
  --faint: #7e8b82;
  --green: #3ee07a;
  --green-ink: #04150c;
  --amber: #ffc14d;
  --danger: #ff8d72;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  --display: "Sora", "Outfit", sans-serif;
