  --panel: #141916;
  --panel-2: #1c2420;
  --line: rgba(232, 240, 230, 0.08);
  --line-strong: rgba(232, 240, 230, 0.16);
  --text: #f4f7f2;
  --muted: #a7b4a8;
  --faint: #7e8b82;
  --green: #3ee07a;
  --green-ink: #04150c;
  --amber: #ffc14d;
  --danger: #ff8d72;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  --display: "Sora", "Outfit", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: dark;
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
}

* { box-sizing: border-box; }
html, body, #root { min-height: 100%; }
body {
  margin: 0;
  background:
    radial-gradient(980px 460px at 8% -12%, rgba(62, 224, 122, 0.1), transparent 52%),
    radial-gradient(720px 380px at 100% 0%, rgba(255, 193, 77, 0.06), transparent 48%),
    var(--bg);
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
h1, p, ul { margin: 0; }
ul { padding: 0; list-style: none; }
::selection { background: rgba(62, 224, 122, 0.35); }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app {
  width: min(1280px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 56px;
}

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  position: relative;
  z-index: 40;
}
h1 {
  font-family: var(--display);
  font-size: 1.85rem;
  line-height: 1;
  letter-spacing: -0.045em;
  font-weight: 700;
}
.top-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.segment {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: #0d100e;
  gap: 2px;
}
.segment button {
  border: 0;
  background: transparent;
  color: var(--muted);
  border-radius: 999px;
  padding: 7px 14px;
  font-size: 13px;
  font-weight: 650;
}
.segment button[aria-pressed="true"] {
  background: var(--text);
  color: #101410;
}

.settings { position: relative; }
.settings-trigger {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: var(--panel);
  font-size: 13px;
  font-weight: 650;
}
.settings-trigger:hover, .segment button:hover { border-color: transparent; }
.settings-trigger:hover { background: var(--panel-2); }

.popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: min(320px, calc(100vw - 40px));
  padding: 14px;
  border-radius: 14px;
  background: #1a211c;
  border: 1px solid var(--line-strong);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
  z-index: 50;
}
.popover-title { font-weight: 700; letter-spacing: -0.02em; }
.help { color: var(--muted); font-size: 13px; line-height: 1.45; }
.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.field { display: flex; flex-direction: column; gap: 6px; color: var(--muted); font-size: 12px; font-weight: 600; }
.field select {
  height: 38px;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: var(--bg);
  color: var(--text);
  padding: 0 10px;
  font-weight: 650;
}
.popover .segment { width: 100%; }
.popover .segment button { flex: 1; }

.stack { display: flex; flex-direction: column; gap: 14px; margin-top: 22px; }

.summary {
  padding: 14px 16px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(62, 224, 122, 0.1), rgba(62, 224, 122, 0.03));
  border: 1px solid rgba(62, 224, 122, 0.24);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.summary.is-empty {
  background: rgba(255, 193, 77, 0.07);
  border-color: rgba(255, 193, 77, 0.28);
}
.summary-kicker { color: var(--muted); font-size: 12px; font-weight: 650; letter-spacing: 0.04em; text-transform: uppercase; }
.summary-main, .badges, .base-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.summary-count { font-size: 1.35rem; letter-spacing: -0.04em; font-weight: 700; }
.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(62, 224, 122, 0.16);
  color: #d8ffe8;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 550;
}
.base-list { display: flex; flex-direction: column; }
.base-line { padding: 8px 0; border-top: 1px solid var(--line); }
.base-line:first-child { border-top: 0; padding-top: 2px; }
.who { min-width: 148px; font-weight: 700; }
.base-count { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 68px; }
.warning { color: var(--amber); font-weight: 700; }
.need-more { color: var(--muted); font-size: 14px; }

.search { position: relative; z-index: 30; max-width: 460px; }
.search-field {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  padding: 0 12px;
  border-radius: 12px;
  border: 1px solid var(--line-strong);
  background: var(--panel);
}
.search-field:focus-within {
  border-color: rgba(62, 224, 122, 0.75);
  box-shadow: 0 0 0 3px rgba(62, 224, 122, 0.16);
}
.search-icon { color: var(--faint); display: grid; }
.search-field input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: none;
  background: transparent;
  font-size: 14px;
}
.search-field input::placeholder { color: var(--faint); }
.clear {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
}
.clear:hover { background: rgba(255, 255, 255, 0.06); color: var(--text); }

.results {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  max-height: 320px;
  overflow: auto;
  padding: 6px;
  border-radius: 14px;
  background: #1a211c;
  border: 1px solid var(--line-strong);
  box-shadow: var(--shadow);
}
.region-label {
  padding: 8px 8px 4px;
  color: var(--faint);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.option {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  text-align: left;
  border: 0;
  background: transparent;
  border-radius: 8px;
  padding: 8px;
}
.option strong { display: block; font-weight: 650; }
.option-country { display: block; color: var(--muted); font-size: 12px; }
.option.is-active { background: rgba(62, 224, 122, 0.14); }
.option:disabled { opacity: 0.45; }
.added { font-size: 11px; color: var(--faint); font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; }
.results-empty { padding: 12px 8px; color: var(--muted); font-size: 13px; }

.board {
  position: relative;
  z-index: 1;
  background: rgba(20, 25, 22, 0.92);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 10px;
  box-shadow: var(--shadow);
}
.desktop-scroll { overflow-x: auto; padding-bottom: 2px; }
.desktop-grid { display: flex; flex-direction: column; gap: 4px; min-width: 1226px; }
.grid-row {
  display: grid;
  grid-template-columns: 180px repeat(24, minmax(0, 1fr)) 36px;
  column-gap: 2px;
  align-items: stretch;
}
.city-meta {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  min-width: 0;
  padding: 6px 8px 6px 10px;
}
.grid-row.is-ref .city-meta {
  background: rgba(62, 224, 122, 0.07);
  border-radius: 10px;
  box-shadow: inset 3px 0 0 var(--green);
}
.head-meta { color: var(--muted); }
.head-kicker { font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 700; }
.head-meta strong { color: var(--text); font-size: 13px; font-weight: 650; }
.city-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  width: fit-content;
  max-width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  font-weight: 700;
  font-size: 14px;
  text-align: left;
  letter-spacing: -0.02em;
}
.city-name:hover { color: var(--green); }
.ref-badge {
  flex: none;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 2px 5px;
  border-radius: 4px;
  background: var(--green);
  color: var(--green-ink);
  line-height: 1.3;
}
.country { color: var(--muted); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.offset { color: #c9d7cb; font-family: var(--mono); font-size: 11px; }

.hour-label, .cell, .m-hour {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 52px;
  border-radius: 7px;
  line-height: 1;
}
.hour-label, .m-hour { min-height: 42px; color: var(--faint); }
.hour-label.is-now, .m-hour.is-now { color: var(--amber); }
.hour-label.is-col-hover, .m-hour.is-col-hover { color: var(--text); }
.cell-main { font-family: var(--mono); font-size: 12px; font-weight: inherit; font-variant-numeric: tabular-nums; }
.cell-suffix {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 3px;
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  opacity: 0.78;
}
.now-dot {
  width: 4px;
  height: 4px;
  margin-top: 4px;
  border-radius: 99px;
  background: transparent;
}
.hour-label.is-now .now-dot { background: var(--amber); }

.cell.sleep { background: #101412; color: #8d9a92; font-weight: 500; }
.cell.awake { background: #24302a; color: #e8f2ea; font-weight: 600; }
.cell.overlap {
  background: var(--green);
  color: var(--green-ink);
  font-weight: 800;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.28);
}
.cell.is-col-hover.awake { background: #2d3b34; }
.cell.is-col-hover.sleep { background: #171c19; }
.cell.is-now { outline: 1px solid rgba(255, 193, 77, 0.5); outline-offset: -1px; }
.day-diff {
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}

.remove {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  margin: auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--faint);
}
.remove:hover { background: rgba(255, 141, 114, 0.14); color: var(--danger); }
.remove-spacer { width: 36px; }

.mobile-board { display: flex; flex-direction: column; gap: 6px; }
.m-head-scroll, .m-body-scroll { overflow-x: auto; }
.m-head-scroll { scrollbar-width: none; }
.m-head-scroll::-webkit-scrollbar { display: none; }
.m-body-inner { display: flex; flex-direction: column; gap: 4px; }
.m-row { display: grid; align-items: stretch; }
.m-head { margin-bottom: 2px; }
.m-row > * { min-width: 0; }
.corner, .m-hour {
  position: sticky;
  left: 0;
  z-index: 2;
  background: #141916;
  border-right: 1px solid var(--line);
}
.corner {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 4px 8px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.25;
  text-align: center;
  min-height: 92px;
}
.m-city {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  min-height: 92px;
  padding: 4px 6px 8px;
}
.m-city .city-name { white-space: normal; }
.m-city .city-name span:first-child { line-height: 1.15; }
.m-city.is-ref { box-shadow: inset 0 -3px 0 var(--green); }
.m-city .city-name { font-size: 13px; }
.m-city .remove { margin: 0; width: 28px; height: 28px; }
.m-hour { border-radius: 7px 0 0 7px; }
.empty { margin: 0; padding: 28px 12px; text-align: center; color: var(--muted); }

.foot {
