.hour-label, .m-hour { min-height: 42px; color: var(--faint); }
.hour-label.is-now, .m-hour.is-now { color: var(--amber); }
.hour-label.is-col-hover, .m-hour.is-col-hover { color: var(--text); }
.cell-main { font-family: var(--mono); font-size: 12px; font-weight: inherit; font-variant-numeric: tabular-nums; }
.cell-suffix {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 3px;
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  opacity: 0.78;
}
.now-dot {
  width: 4px;
  height: 4px;
  margin-top: 4px;
  border-radius: 99px;
  background: transparent;
}
.hour-label.is-now .now-dot { background: var(--amber); }

.cell.sleep { background: #101412; color: #8d9a92; font-weight: 500; }
.cell.awake { background: #24302a; color: #e8f2ea; font-weight: 600; }
.cell.overlap {
  background: var(--green);
  color: var(--green-ink);
  font-weight: 800;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.28);
}
.cell.is-col-hover.awake { background: #2d3b34; }
.cell.is-col-hover.sleep { background: #171c19; }
.cell.is-now { outline: 1px solid rgba(255, 193, 77, 0.5); outline-offset: -1px; }
.day-diff {
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}

.remove {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  margin: auto;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--faint);
}
.remove:hover { background: rgba(255, 141, 114, 0.14); color: var(--danger); }
.remove-spacer { width: 36px; }

.mobile-board { display: flex; flex-direction: column; gap: 6px; }
.m-head-scroll, .m-body-scroll { overflow-x: auto; }
.m-head-scroll { scrollbar-width: none; }
.m-head-scroll::-webkit-scrollbar { display: none; }
.m-body-inner { display: flex; flex-direction: column; gap: 4px; }
.m-row { display: grid; align-items: stretch; }
.m-head { margin-bottom: 2px; }
.m-row > * { min-width: 0; }
.corner, .m-hour {
  position: sticky;
  left: 0;
  z-index: 2;
  background: #141916;
  border-right: 1px solid var(--line);
}
.corner {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  padding: 0 4px 8px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.25;
  text-align: center;
  min-height: 92px;
}
.m-city {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  min-height: 92px;
  padding: 4px 6px 8px;
}
.m-city { overflow: hidden; }
.m-city .city-name {
  width: 100%;
  white-space: normal;
}
.m-city .city-name span:first-child {
  line-height: 1.15;
  overflow-wrap: anywhere;
}
.m-city.is-ref { box-shadow: inset 0 -3px 0 var(--green); }
.m-city .city-name { font-size: 13px; }
.m-city .remove { margin: 0; width: 28px; height: 28px; }
.m-hour { border-radius: 7px 0 0 7px; }
.empty { margin: 0; padding: 28px 12px; text-align: center; color: var(--muted); }

.foot {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 18px;
  color: var(--muted);
  font-size: 13px;
}
.legend { display: flex; flex-wrap: wrap; gap: 14px; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
.swatch.sleep { background: #101412; box-shadow: inset 0 0 0 1px #33403a; }
.swatch.awake { background: #24302a; }
.swatch.overlap { background: var(--green); }
.hint { color: var(--text); font-weight: 650; }

button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 2px;
}
.search-field input:focus-visible { outline: none; }

@media (max-width: 767px) {
  .app { width: min(100% - 24px, 1280px); padding-top: 18px; }
  .top { align-items: stretch; flex-direction: column; }
