  .top-actions { width: 100%; display: grid; grid-template-columns: 1fr; justify-content: stretch; }
  .segment, .settings, .settings-trigger { width: 100%; }
  .segment button { flex: 1; }
  .settings-trigger { justify-content: center; }
  .search { max-width: none; }
  .who { min-width: 0; width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
}

