:root {
  --bg: #090b0a;
  --panel: #141916;
  --panel-2: #1c2420;
  --line: rgba(232, 240, 230, 0.08);
  --line-strong: rgba(232, 240, 230, 0.16);
  --text: #f4f7f2;
  --muted: #a7b4a8;
  --faint: #7e8b82;
  --green: #3ee07a;
  --green-ink: #04150c;
  --amber: #ffc14d;
  --danger: #ff8d72;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
  --sans: "Outfit", "Avenir Next", "Segoe UI", sans-serif;
  --display: "Sora", "Outfit", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
  color-scheme: dark;
  font-family: var(--sans);
  background: var(--bg);
  color: var(--text);
}

* { box-sizing: border-box; }
html, body, #root { min-height: 100%; }
body {
  margin: 0;
  background:
    radial-gradient(980px 460px at 8% -12%, rgba(62, 224, 122, 0.1), transparent 52%),
    radial-gradient(720px 380px at 100% 0%, rgba(255, 193, 77, 0.06), transparent 48%),
    var(--bg);
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
h1, p, ul { margin: 0; }
ul { padding: 0; list-style: none; }
::selection { background: rgba(62, 224, 122, 0.35); }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app {
  width: min(1280px, calc(100% - 32px));
  margin: 0 auto;
  padding: 28px 0 56px;
}

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  position: relative;
  z-index: 40;
}
h1 {
  font-family: var(--display);
  font-size: 1.85rem;
  line-height: 1;
  letter-spacing: -0.045em;
  font-weight: 700;
}
.top-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.segment {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: #0d100e;
  gap: 2px;
}
.segment button {
  border: 0;
  background: transparent;
  color: var(--muted);
  border-radius: 999px;
  padding: 7px 14px;
  font-size: 13px;
  font-weight: 650;
}
.segment button[aria-pressed="true"] {
  background: var(--text);
  color: #101410;
}

.settings { position: relative; }
.settings-trigger {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 38px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: var(--panel);
  font-size: 13px;
  font-weight: 650;
}
.settings-trigger:hover, .segment button:hover { border-color: transparent; }
.settings-trigger:hover { background: var(--panel-2); }

.popover {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: min(320px, calc(100vw - 40px));
  padding: 14px;
  border-radius: 14px;
  background: #1a211c;
  border: 1px solid var(--line-strong);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
  z-index: 50;
}
.popover-title { font-weight: 700; letter-spacing: -0.02em; }
.help { color: var(--muted); font-size: 13px; line-height: 1.45; }
