.city-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  width: fit-content;
  max-width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  font-weight: 700;
  font-size: 14px;
  text-align: left;
  letter-spacing: -0.02em;
}
