.swatch.sleep { background: #101412; box-shadow: inset 0 0 0 1px #33403a; }
.swatch.awake { background: #24302a; }
.swatch.overlap { background: var(--green); }
.hint { color: var(--text); font-weight: 650; }

button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 2px;
}
.search-field input:focus-visible { outline: none; }

@media (max-width: 767px) {
  .app { width: min(100% - 24px, 1280px); padding-top: 18px; }
  .top { align-items: stretch; flex-direction: column; }
  h1 { font-size: 1.6rem; }
  .top-actions { width: 100%; display: grid; grid-template-columns: 1fr; justify-content: stretch; }
  .segment, .settings, .settings-trigger { width: 100%; }
  .segment button { flex: 1; }
  .settings-trigger { justify-content: center; }
  .search { max-width: none; }
  .who { min-width: 0; width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
}

args.command:
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
"$CHROME" --headless=new --disable-gpu --remote-debugging-port=9333 --window-size=390,844 http://127.0.0.1:9351 >/tmp/chrome-debug.log 2>&1 &
echo $!
sleep 1.5
node --input-type=module <<'EOF'
const targets = await fetch('http://127.0.0.1:9333/json').then((r) => r.json());
const page = targets.find((t) => t.type === 'page' && t.webSocketDebuggerUrl);
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve);
  ws.addEventListener('error', reject);
});
let id = 0;
function send(method, params = {}) {
  const messageId = ++id;
  return new Promise((resolve) => {
    const onMessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.id === messageId) {
        ws.removeEventListener('message', onMessage);
        resolve(data.result);
      }
    };
    ws.addEventListener('message', onMessage);
    ws.send(JSON.stringify({ id: messageId, method, params }));
  });
}
await send('Runtime.enable');
const result = await send('Runtime.evaluate', {
  expression: `(() => {
    const board = document.querySelector('.mobile-board');
    const track = document.querySelector('.m-track');
    const cities = [...document.querySelectorAll('.m-city')].map((el) => ({
      text: el.innerText.replace(/\\n/g, ' | '),
      w: Math.round(el.getBoundingClientRect().width),
      right: Math.round(el.getBoundingClientRect().right),
    }));
    return JSON.stringify({
      inner: window.innerWidth,
      doc: document.documentElement.scrollWidth,
      board: board ? Math.round(board.getBoundingClientRect().width) : null,
      track: track ? Math.round(track.getBoundingClientRect().width) : null,
      cities,
    });
  })()`,
  returnByValue: true,
});
console.log(result.result.value);
ws.close();
EOF
kill $(lsof -ti tcp:9333) 2>/dev/null || true

