args.command:
CHROME="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
"$CHROME" --headless=new --disable-gpu --remote-debugging-port=9333 about:blank >/tmp/chrome-debug.log 2>&1 &
sleep 0.8
node --input-type=module <<'EOF'
const targets = await fetch('http://127.0.0.1:9333/json').then((r) => r.json());
const page = targets.find((t) => t.type === 'page' && t.webSocketDebuggerUrl);
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve);
  ws.addEventListener('error', reject);
});
let id = 0;
function send(method, params = {}) {
  const messageId = ++id;
  return new Promise((resolve) => {
    const onMessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.id === messageId) {
        ws.removeEventListener('message', onMessage);
        resolve(data.result);
      }
    };
    ws.addEventListener('message', onMessage);
    ws.send(JSON.stringify({ id: messageId, method, params }));
  });
}
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await send('Page.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:9351' });
await new Promise((r) => setTimeout(r, 1200));
const result = await send('Runtime.evaluate', {
  expression: `(() => {
    const board = document.querySelector('.mobile-board');
    const track = document.querySelector('.m-track');
    const cities = [...document.querySelectorAll('.m-city')].map((el) => ({
      text: el.innerText.replaceAll('\\n', ' | '),
      w: Math.round(el.getBoundingClientRect().width),
      left: Math.round(el.getBoundingClientRect().left),
      right: Math.round(el.getBoundingClientRect().right),
    }));
    const scroll = document.querySelector('.m-head-scroll');
    return JSON.stringify({
      inner: window.innerWidth,
      doc: document.documentElement.scrollWidth,
      layout: document.querySelector('.app')?.dataset.layout,
      board: board && Math.round(board.getBoundingClientRect().width),
      track: track && Math.round(track.getBoundingClientRect().width),
      scrollClient: scroll && scroll.clientWidth,
      scrollWidth: scroll && scroll.scrollWidth,
      cities,
      title: document.querySelector('h1')?.textContent,
    });
  })()`,
  returnByValue: true,
});
console.log(result.result.value);
ws.close();
EOF
kill $(lsof -ti tcp:9333) 2>/dev/null || true

